from pathlib import Path
from html.parser import HTMLParser
from hashlib import sha256
import json, re

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden += 1
        if tag in {'p', 'li', 'h1', 'h2', 'h3', 'tr'}:
            self.parts.append('\n')
    def handle_endtag(self, tag):
        if tag in {'script', 'style'} and self.hidden:
            self.hidden -= 1
    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data)

raw = Path('products/services/catalogue-gumroad/raw')
records = []
for path in sorted(raw.glob('*.html')):
    data = path.read_bytes()
    parser = VisibleText()
    parser.feed(data.decode('utf-8', errors='replace'))
    lines = [' '.join(line.split()) for line in ''.join(parser.parts).splitlines()]
    matches = [line[:700] for line in lines if re.search(r'\b(Canada|Canadian|CAD|payout|bank account|monthly fee|transaction fee|artificial intelligence|AI.generated|prohibited|redistribution)\b', line, re.I)]
    records.append({'path': str(path), 'sha256': sha256(data).hexdigest(), 'candidate_passages': list(dict.fromkeys(matches))[:30]})
report = {'source_passages_require_context_check': True, 'captures': records}
out = Path('products/services/catalogue-gumroad/source-passages.json')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(report, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(f'Wrote passages from {len(records)} saved official captures to {out}')
